use serde_json::{Value, from_str};

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut map: std::collections::HashMap<i64, i64> = std::collections::HashMap::new();
    for row in input.as_array().unwrap() {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        map.entry(key).or_insert(value);
    }

    let mut sorted_keys: Vec<i64> = map.keys().cloned().collect();
    sorted_keys.sort_unstable();

    let mut result: Vec<Vec<i64>> = Vec::new();
    for key in sorted_keys {
        result.push(vec![key, map[key]]);
    }

    serde_json::to_value(result).unwrap()
}
